import{_ as e}from"./chunks/dashboard-home-stopped.DxCzv0yb.js";import{_ as a}from"./chunks/dashboard-docker-error.CtiVSRfK.js";import{_ as r,o,c as s,a2 as n}from"./chunks/framework.Dhf_H6O0.js";const f=JSON.parse('{"title":"The Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"using-the-app/dashboard.md","filePath":"using-the-app/dashboard.md"}'),i={name:"using-the-app/dashboard.md"};function h(l,t,d,c,g,p){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="the-dashboard" tabindex="-1">The Dashboard <a class="header-anchor" href="#the-dashboard" aria-label="Permalink to &quot;The Dashboard&quot;">​</a></h1><p>The Dashboard is the home screen of MCPBehindIT. It gives you a quick overview of everything: Docker status, gateway state, your servers, and connection URLs.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p><img src="'+e+'" alt="MCPBehindIT Dashboard"></p><h3 id="status-badge-top-right" tabindex="-1">Status badge (top-right) <a class="header-anchor" href="#status-badge-top-right" aria-label="Permalink to &quot;Status badge (top-right)&quot;">​</a></h3><p>The colored dot in the top-right corner shows the overall state at a glance:</p><table tabindex="0"><thead><tr><th>Badge</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Running</strong> (green)</td><td>Gateway is up and serving requests</td></tr><tr><td><strong>Stopped</strong> (gray)</td><td>Gateway is not running</td></tr><tr><td><strong>Error</strong> (red)</td><td>Something went wrong — check the stack card for details</td></tr><tr><td><strong>Starting…</strong> / <strong>Pulling…</strong> (yellow)</td><td>Gateway is starting or pulling the Docker image</td></tr></tbody></table><h3 id="phase-strip" tabindex="-1">Phase strip <a class="header-anchor" href="#phase-strip" aria-label="Permalink to &quot;Phase strip&quot;">​</a></h3><p>The horizontal bar below the heading shows three phases:</p><ol><li><strong>DOCKER</strong> — Is Docker Desktop reachable?</li><li><strong>GATEWAY</strong> — Is the gateway container running?</li><li><strong>SERVERS</strong> — How many server profiles exist and how many are enabled?</li></ol><p>Each phase has a colored dot: green (ok), gray (inactive), or red (problem).</p><h3 id="three-tabs" tabindex="-1">Three tabs <a class="header-anchor" href="#three-tabs" aria-label="Permalink to &quot;Three tabs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tab</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Stack</strong></td><td>Gateway controls — Start, Stop, Apply &amp; Restart. Error messages and progress logs appear here.</td></tr><tr><td><strong>Clients</strong></td><td>Connection URLs for each enabled server. Appears once the gateway has run at least once.</td></tr><tr><td><strong>Documents</strong></td><td>Local RAG file explorer — index, refresh, and manage your document files.</td></tr></tbody></table><h2 id="stack-tab" tabindex="-1">Stack tab <a class="header-anchor" href="#stack-tab" aria-label="Permalink to &quot;Stack tab&quot;">​</a></h2><p>This is the default view. It contains:</p><ul><li><strong>Tool gateway</strong> card — Current status and action buttons.</li><li><strong>Quick stats</strong> (when running) — Number of server profiles, how many are active, and the base URL.</li></ul><h3 id="error-states" tabindex="-1">Error states <a class="header-anchor" href="#error-states" aria-label="Permalink to &quot;Error states&quot;">​</a></h3><p>If Docker is unavailable, the card shows an error with a <strong>Details</strong> expander:</p><p><img src="'+a+'" alt="Docker error on Dashboard"></p><p>If the port is already in use, you&#39;ll see a message suggesting to either stop the other process or change the port in Settings.</p><h2 id="clients-tab" tabindex="-1">Clients tab <a class="header-anchor" href="#clients-tab" aria-label="Permalink to &quot;Clients tab&quot;">​</a></h2><p>Once the gateway has started at least once, the Clients tab shows:</p><ul><li>A <strong>URL table</strong> with one row per enabled server. Each row has buttons to: <ul><li><strong>Copy base</strong> — the server&#39;s base URL</li><li><strong>Copy OpenAPI</strong> — the OpenAPI spec URL (what you paste into Open WebUI)</li><li><strong>Copy OpenAPI JSON</strong> — the raw JSON spec URL</li><li><strong>Open docs</strong> — opens the interactive API docs in your browser</li></ul></li><li><strong>Bulk copy</strong> — copy all base URLs or all OpenAPI URLs at once.</li><li><strong>Open WebUI</strong> — expandable step-by-step instructions for connecting to Open WebUI.</li></ul><p>See <a href="./../connecting-tools/overview.html">Connecting Your Tools</a> for a detailed walkthrough.</p><h2 id="documents-tab" tabindex="-1">Documents tab <a class="header-anchor" href="#documents-tab" aria-label="Permalink to &quot;Documents tab&quot;">​</a></h2><p>If you&#39;ve added the <strong>MCP Local RAG</strong> server, the Documents tab shows a file explorer with:</p><ul><li>A list of files in your indexed folder</li><li>Status for each file (indexed / not yet indexed)</li><li>Buttons to <strong>Refresh list</strong>, <strong>Index selected</strong>, and <strong>Select not indexed</strong></li></ul><p>See <a href="./../catalog/local-rag.html">Local Document Search</a> for setup instructions.</p>',28)])])}const y=r(i,[["render",h]]);export{f as __pageData,y as default};
